let state = loadState();
function loadState(){ try { const raw=window.MistakeRepository.read('mistake-center-demo'); return raw ? {...seed,...raw} : structuredClone(seed); } catch { return structuredClone(seed); } }
function saveState(){ return window.MistakeRepository.write('mistake-center-demo', state); }
function setState(patch){ state={...state,...patch}; saveState(); render(); }
function showToast(message, tone=''){ const region=document.querySelector('#toast-region'); region.innerHTML=`<div class="toast ${tone}">${message}</div>`; setTimeout(()=>{ if(region.firstElementChild) region.innerHTML=''; },3000); }
function statusLabel(status){ return {uploaded:'已上传',recognizing:'AI识别中',needs_confirmation:'等待确认',needs_teacher_review:'待老师复核',confirmed:'已确认',save_failed:'同步失败',ready_for_practice:'可生成练习',generating:'练习生成中',assigned:'已布置',in_progress:'作答中',submitted:'已提交',completed:'已完成'}[status] || status; }
function statusPill(status){ const cls = ['completed','confirmed','assigned'].includes(status) ? 'pill-green' : ['needs_confirmation','needs_teacher_review','save_failed','generating'].includes(status) ? 'pill-orange' : status==='submitted' ? 'pill-blue' : 'pill-gray'; return `<span class="pill ${cls}">${statusLabel(status)}</span>`; }
function pageTitle(){ const labels={home:'总览',upload:'上传作业',confirm:'确认识别结果',practice:'练习管理',progress:'学习进展',today:'今日练习',mistakes:'我的错题',review:'待复核',students:'学生管理',diagnosis:'班级诊断',assign:'练习布置',practiceDetail:'在线练习',results:'提交结果',taskDetail:'错题任务详情'}; return labels[state.page] || '总览'; }
function render(){ document.querySelector('#app').innerHTML = shell(); bindEvents(); }
function shell(){ const meta=roleMeta[state.role]; return `<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">错</div><div><h1>错题任务中心</h1><p>让每一道错题都有下一步</p></div></div><div class="nav-label">工作台</div><nav class="nav-list">${meta.nav.map(([id,label,ico])=>`<button class="nav-item ${state.page===id?'active':''}" data-nav="${id}">${icon(ico)}<span>${label}</span>${id==='confirm'&&state.task.questions.filter(q=>q.reviewStatus==='pending').length?'<span class="pill pill-orange" style="margin-left:auto;padding:3px 6px">2</span>':''}</button>`).join('')}</nav><div class="side-bottom"><p class="demo-note">演示角色切换仅用于产品演示；生产环境应由真实账号和服务端权限控制。</p><div class="user-card"><div class="avatar">${meta.initials}</div><div class="user-meta"><strong>${meta.name}</strong><span>${meta.role} · 初一（3）班</span></div><select class="select-role" id="role-switch" aria-label="切换演示角色"><option value="student" ${state.role==='student'?'selected':''}>学生</option><option value="parent" ${state.role==='parent'?'selected':''}>家长</option><option value="teacher" ${state.role==='teacher'?'selected':''}>老师</option></select></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">工作台 / <strong>${pageTitle()}</strong></div><div class="top-actions"><button class="icon-button" data-action="notifications" aria-label="通知中心">${icon('bell')}<span class="notification-dot"></span></button><button class="icon-button" data-action="help" aria-label="帮助">${icon('help')}</button></div></header><section class="content">${pageView()}</section></main></div>`; }
function pageView(){ if(state.role==='student') return studentView(); if(state.role==='teacher') return teacherView(); return parentView(); }
function parentView(){ switch(state.page){ case 'upload': return parentUpload(); case 'confirm': return parentConfirm(); case 'practice': return parentPractice(); case 'progress': return progressView('parent'); case 'taskDetail': return taskDetail(); default:return parentHome(); } }
function parentHome(){ const pending=state.task.questions.filter(q=>q.reviewStatus==='pending').length; return `<div class="page-head"><div><div class="eyebrow">家长工作台 · 今日</div><h1 class="page-title">把错题变成下一次进步</h1><p class="page-subtitle">李明的学习任务都在这里，先处理待确认的识别结果。</p></div><div class="head-actions"><button class="btn btn-primary" data-nav="upload">${icon('upload')}上传一份新作业</button></div></div><div class="stats-grid"><div class="stat-card"><div class="stat-top"><span>待确认任务</span><span class="stat-icon tint-orange">${icon('clock')}</span></div><div class="stat-value">${pending}</div><div class="stat-foot">有 1 道题需要老师复核</div></div><div class="stat-card"><div class="stat-top"><span>本周已生成练习</span><span class="stat-icon tint-blue">${icon('book')}</span></div><div class="stat-value">3</div><div class="stat-foot">较上周多 1 份</div></div><div class="stat-card"><div class="stat-top"><span>练习完成率</span><span class="stat-icon tint-green">${icon('trend')}</span></div><div class="stat-value">78%</div><div class="stat-foot">近 7 天 · 稳定提升</div></div><div class="stat-card"><div class="stat-top"><span>当前薄弱知识点</span><span class="stat-icon tint-purple">${icon('alert')}</span></div><div class="stat-value" style="font-size:22px">绝对值方程</div><div class="stat-foot">建议再练 1 组</div></div></div><div class="grid-2"><div class="card"><div class="card-head"><div><h2>最近任务</h2><p>按最近活动排序</p></div><button class="btn btn-ghost btn-sm" data-nav="confirm">查看全部 ${icon('chevron')}</button></div><div class="card-body"><div class="list"><div class="list-row"><div class="row-thumb">${icon('image')}</div><div class="row-main"><strong>${state.task.sourceFileName}</strong><span>李明 · ${state.task.uploadedAt} · 识别 7 题，错题 2 题</span></div><div class="row-right">${statusPill(state.task.status)}<button class="btn btn-secondary btn-sm" data-nav="confirm">去确认</button></div></div><div class="list-row"><div class="row-thumb">${icon('book')}</div><div class="row-main"><strong>周一错题强化练习</strong><span>6 道题 · 预计 20 分钟 · 截止 09-16</span></div><div class="row-right">${statusPill('assigned')}<button class="btn btn-secondary btn-sm" data-nav="practice">查看</button></div></div><div class="list-row"><div class="row-thumb">${icon('clipboard')}</div><div class="row-main"><strong>上周几何练习</strong><span>已完成 · 正确率 83%</span></div><div class="row-right">${statusPill('completed')}<button class="btn btn-secondary btn-sm" data-nav="progress">查看</button></div></div></div></div></div><div class="card"><div class="card-head"><div><h2>孩子近期薄弱知识点</h2><p>来自近 30 天错题</p></div></div><div class="card-body"><div class="knowledge-list"><div class="knowledge-item"><span class="label">绝对值方程</span><div class="progress-track"><div class="progress-fill" style="width:82%;background:#d77b28"></div></div><span class="value">82%</span></div><div class="knowledge-item"><span class="label">平行线与角</span><div class="progress-track"><div class="progress-fill" style="width:58%;background:#6f8fc3"></div></div><span class="value">58%</span></div><div class="knowledge-item"><span class="label">一元一次方程</span><div class="progress-track"><div class="progress-fill" style="width:34%;background:#65a986"></div></div><span class="value">34%</span></div></div><div class="notice notice-info mt-18">${icon('help')}<div><strong>怎么看这份数据</strong>百分比表示近期错题占比，越高越建议优先练习。</div></div></div></div></div>`; }
function taskTimeline(current='needs_confirmation'){ const steps=[['uploaded','已上传'],['recognizing','AI识别中'],['needs_confirmation','等待确认'],['needs_teacher_review','数学冲突复核'],['confirmed','已确认'],['generating','练习生成中'],['assigned','已布置'],['in_progress','学生作答中'],['submitted','已提交'],['completed','已完成']]; const idx=steps.findIndex(s=>s[0]===current); return `<div class="timeline">${steps.map(([key,label],i)=>{let cls=i<idx?'done':i===idx?'active':''; if(key==='needs_teacher_review'&&state.task.questions.some(q=>q.conflictStatus==='teacher_marking_conflict')) cls=i<=idx?'active':cls; return `<div class="timeline-step ${cls}" data-action="timeline" data-status="${key}" tabindex="0"><span class="timeline-dot">${i<idx?icon('check','icon'):i===idx?'<span style="font-size:12px">•</span>':i+1}</span><span>${label}</span></div>`}).join('')}</div>`; }
function parentUpload(){ return `<div class="page-head"><div><div class="eyebrow">家长工作台 · 新任务</div><h1 class="page-title">上传一份新作业</h1><p class="page-subtitle">支持 JPG、PNG，单张图片不超过 10MB。</p></div></div><div class="stepper"><div class="stepper-item active"><span class="stepper-num">1</span>上传图片</div><div class="stepper-item"><span class="stepper-num">2</span>AI识别</div><div class="stepper-item"><span class="stepper-num">3</span>家长确认</div><div class="stepper-item"><span class="stepper-num">4</span>选择练习</div><div class="stepper-item"><span class="stepper-num">5</span>生成完成</div></div><div class="grid-2"><div class="card"><div class="card-head"><div><h2>第一步 · 上传作业图片</h2><p>图片清晰、完整，识别会更准确</p></div></div><div class="card-body"><div class="upload-drop"><div><div class="upload-icon">${icon('upload','icon')}</div><strong>拖拽图片到这里，或点击选择文件</strong><p>JPG、PNG · 最大 10MB · 支持单张上传</p><button class="btn btn-primary" data-action="choose-file">选择图片</button><input class="hide" type="file" id="file-input" accept="image/png,image/jpeg" /></div></div><div class="notice notice-info mt-18">${icon('help')}<div><strong>家长只需要确认识别内容</strong>数学结论由 AI 和老师复核，遇到冲突会自动交给老师。</div></div></div></div><div class="card"><div class="card-head"><div><h2>上传前检查</h2><p>3 个小提醒，帮助一次识别成功</p></div></div><div class="card-body"><div class="detail-list"><div class="detail-item"><h3>${icon('check')} 光线均匀</h3><p>避免反光和阴影，题目边缘完整可见。</p></div><div class="detail-item"><h3>${icon('check')} 一页一张</h3><p>如果作业有多页，建议逐页上传并确认。</p></div><div class="detail-item"><h3>${icon('check')} 保留批改痕迹</h3><p>老师的对错标记会帮助系统区分正确题与错题。</p></div></div></div></div></div>`; }
function parentConfirm(){ const visible=state.task.questions.filter(q=>q.teacherMarkingResult!=='correct' || q.conflictStatus!=='none'); return `<div class="page-head"><div><div class="eyebrow">家长工作台 · 识别确认</div><h1 class="page-title">确认错题识别结果</h1><p class="page-subtitle">请确认需要强化的题目，冲突题会交给老师复核。</p></div><div class="head-actions"><button class="btn btn-secondary" data-nav="taskDetail">查看任务详情</button><button class="btn btn-primary" data-nav="practice">下一步：选择练习 ${icon('arrow')}</button></div></div>${state.task.saveStatus==='failed'?'<div class="notice notice-warn" style="margin-bottom:18px">'+icon('alert')+'<div><strong>错题暂未同步到历史记录，但仍可基于本次识别结果生成练习。</strong><span>你可以先继续完成本次练习，稍后再重新同步。</span> <button class="btn btn-ghost btn-sm" data-action="resync">重新同步</button></div></div>':''}<div class="card" style="margin-bottom:18px">${taskTimeline('needs_confirmation')}</div><div class="split"><div class="card"><div class="card-head"><div><h2>原始作业图片</h2><p>${state.task.sourceFileName}</p></div><div class="head-actions"><button class="image-tool" data-action="zoom" aria-label="放大">${icon('expand')}</button><button class="image-tool" data-action="rotate" aria-label="旋转">${icon('rotate')}</button></div></div><div class="card-body"><div class="task-image"><div class="worksheet-lines"></div><div class="image-tools"><button class="image-tool" data-action="zoom" aria-label="放大">${icon('expand')}</button><button class="image-tool" data-action="rotate" aria-label="旋转">${icon('rotate')}</button></div></div><p class="muted" style="font-size:11px;margin:10px 0 0">点击图片工具可查看清晰版本，不影响识别内容。</p></div></div><div><div class="notice notice-info" style="margin-bottom:12px">${icon('help')}<div><strong>这里展示需要你确认的题目</strong>共 ${visible.length} 道，正确题已自动归档。</div></div>${visible.map(questionCard).join('')}</div></div>`; }
function questionCard(q){ const conflict=q.conflictStatus==='teacher_marking_conflict'; return `<article class="question-card" data-question="${q.id}"><div class="question-head"><span class="question-no">第 ${q.questionNo} 题</span><div style="display:flex;gap:6px;align-items:center">${conflict?'<span class="pill pill-orange">教师批改与数学复核结果不一致</span>':''}${q.recognitionConfidence==='low'?'<span class="pill pill-red">低置信度</span>':''}</div></div><p class="question-text">${q.questionText}</p><div class="answer-box"><div><label>学生作答</label><span>${q.studentWork}</span></div><div><label>教师批改</label><span>${q.teacherMarkingResult==='incorrect'?'错误':'待确认'}${q.teacherWrittenAnswer?` · ${q.teacherWrittenAnswer}`:''}</span></div><div><label>AI 数学复核</label><span>${q.aiMathVerdict==='incorrect'?'判断为错误':q.aiMathVerdict==='insufficient_information'?'条件不足':'判断为正确'}</span></div><div><label>识别出的正确答案</label><span>${q.verifiedCorrectAnswer || '待补充'}</span></div></div><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px"><span class="pill pill-blue">${q.knowledgePoint}</span><span class="confidence">识别置信度：${q.recognitionConfidence==='high'?'高':q.recognitionConfidence==='medium'?'中':'低'}</span></div>${conflict?'<div class="notice notice-warn" style="margin-bottom:12px">'+icon('alert')+'<div><strong>这道题不能直接用于生成练习</strong>请提交老师复核，确认后才会进入练习。</div></div>':''}<div class="question-actions">${conflict?'<button class="btn btn-warn btn-sm" data-action="send-review" data-id="'+q.id+'">交给老师复核</button>':'<button class="btn btn-secondary btn-sm" data-action="confirm-question" data-id="'+q.id+'">'+icon('check')+'确认无误</button>'}<button class="btn btn-secondary btn-sm" data-action="edit-question" data-id="${q.id}">${icon('edit')}修改识别内容</button>${!conflict?'<button class="btn btn-ghost btn-sm" data-action="not-mistake" data-id="'+q.id+'">标记不是错题</button>':''}</div></article>`; }
function parentPractice(){ const selected=state.task.questions.filter(q=>state.selectedQuestions.includes(q.id) && q.conflictStatus!=='teacher_marking_conflict'); return `<div class="page-head"><div><div class="eyebrow">家长工作台 · 练习设置</div><h1 class="page-title">生成针对性练习</h1><p class="page-subtitle">从已确认错题中选择强化范围，系统会自动生成新题。</p></div><div class="head-actions"><button class="btn btn-secondary" data-nav="confirm">返回确认</button><button class="btn btn-primary" data-action="generate">生成针对性练习 ${icon('arrow')}</button></div></div><div class="stepper"><div class="stepper-item done"><span class="stepper-num">${icon('check')}</span>上传图片</div><div class="stepper-item done"><span class="stepper-num">${icon('check')}</span>AI识别</div><div class="stepper-item done"><span class="stepper-num">${icon('check')}</span>家长确认</div><div class="stepper-item active"><span class="stepper-num">4</span>选择练习</div><div class="stepper-item"><span class="stepper-num">5</span>生成完成</div></div><div class="grid-2"><div class="card"><div class="card-head"><div><h2>选择需要强化的错题</h2><p>冲突题需老师复核后才可选择</p></div><span class="pill pill-blue">已选 ${selected.length} 道</span></div><div class="card-body">${state.task.questions.filter(q=>q.teacherMarkingResult!=='correct').map(q=>`<label class="choice" style="align-items:flex-start;opacity:${q.conflictStatus==='teacher_marking_conflict'?'0.58':'1'}"><input type="checkbox" data-question-check="${q.id}" ${state.selectedQuestions.includes(q.id)?'checked':''} ${q.conflictStatus==='teacher_marking_conflict'?'disabled':''}/><span><strong>第 ${q.questionNo} 题 · ${q.knowledgePoint}</strong><small style="display:block;color:var(--muted);margin-top:4px">${q.errorType || '待确认'} · ${q.questionText}</small>${q.conflictStatus==='teacher_marking_conflict'?'<small style="display:block;color:var(--orange);margin-top:4px">等待老师复核后开放</small>':''}</span></label>`).join('')}</div></div><div class="card"><div class="card-head"><div><h2>练习参数</h2><p>可以随时调整，右侧实时预览</p></div></div><div class="card-body"><div class="field"><label for="per-question">每道错题生成</label><select id="per-question"><option value="1">1 道</option><option value="2" selected>2 道</option><option value="3">3 道</option><option value="5">5 道</option></select></div><div class="field-row"><div class="field"><label for="difficulty">难度</label><select id="difficulty"><option value="basic">基础</option><option value="standard" selected>标准</option><option value="advanced">提高</option></select></div><div class="field"><label for="type">题型</label><select id="type"><option>混合题型</option><option>选择题</option><option>填空题</option><option>解答题</option></select></div></div><label class="check-row"><input type="checkbox" checked /> 混入历史薄弱知识点</label><div class="notice notice-warn mt-18">${icon('alert')}<div><strong>同步状态：暂未保存</strong>错题暂未同步到历史记录，但仍可基于本次识别结果生成练习。<button class="btn btn-ghost btn-sm" data-action="resync">重新同步</button></div></div></div></div></div><div class="card section-gap"><div class="card-head"><div><h2>生成预览</h2><p>生成后可在练习管理中查看</p></div></div><div class="card-body"><div class="result-cards" style="margin:0;grid-template-columns:repeat(4,1fr)"><div class="result-mini"><span>已选错题</span><strong>${selected.length}</strong></div><div class="result-mini"><span>预计生成</span><strong>${selected.length*2} 题</strong></div><div class="result-mini"><span>知识点</span><strong style="font-size:14px">${selected.map(q=>q.knowledgePoint).join('、') || '未选择'}</strong></div><div class="result-mini"><span>预计用时</span><strong>约 ${Math.max(8,selected.length*8)} 分钟</strong></div></div></div></div>`; }
function progressView(){ return `<div class="page-head"><div><div class="eyebrow">学习进展</div><h1 class="page-title">看见每一次小进步</h1><p class="page-subtitle">按知识点和练习记录，找到下一步最值得投入的地方。</p></div><div class="head-actions"><button class="btn btn-secondary" data-action="export">${icon('download')}导出学习报告</button></div></div><div class="stats-grid"><div class="stat-card"><div class="stat-top"><span>近 7 天练习</span><span class="stat-icon tint-blue">${icon('book')}</span></div><div class="stat-value">18</div><div class="stat-foot">完成 14 道 · 正确率 78%</div></div><div class="stat-card"><div class="stat-top"><span>错题减少</span><span class="stat-icon tint-green">${icon('trend')}</span></div><div class="stat-value">24%</div><div class="stat-foot">相比上一个周期</div></div><div class="stat-card"><div class="stat-top"><span>连续学习</span><span class="stat-icon tint-orange">${icon('clock')}</span></div><div class="stat-value">6 天</div><div class="stat-foot">保持节奏，效果更好</div></div><div class="stat-card"><div class="stat-top"><span>已掌握知识点</span><span class="stat-icon tint-purple">${icon('check')}</span></div><div class="stat-value">12</div><div class="stat-foot">共 16 个知识点</div></div></div><div class="grid-2"><div class="card"><div class="card-head"><div><h2>正确率变化</h2><p>最近 7 次练习</p></div></div><div class="card-body"><div class="trend"><svg viewBox="0 0 580 140" preserveAspectRatio="none"><path d="M25 118H570M25 88H570M25 58H570M25 28H570" stroke="#edf1f6"/><path d="M25 105 C80 100 94 86 140 91 S210 70 250 76 S325 52 360 61 S420 38 455 45 S525 22 570 30" fill="none" stroke="#2c67c7" stroke-width="3"/><path d="M25 105 C80 100 94 86 140 91 S210 70 250 76 S325 52 360 61 S420 38 455 45 S525 22 570 30 L570 140 L25 140Z" fill="rgba(44,103,199,.08)"/><g fill="#2c67c7"><circle cx="25" cy="105" r="4"/><circle cx="140" cy="91" r="4"/><circle cx="250" cy="76" r="4"/><circle cx="360" cy="61" r="4"/><circle cx="455" cy="45" r="4"/><circle cx="570" cy="30" r="4"/></g></svg><div style="display:flex;justify-content:space-between;color:var(--muted);font-size:10px"><span>09/08</span><span>09/10</span><span>09/12</span><span>09/14</span></div></div></div></div><div class="card"><div class="card-head"><div><h2>知识点掌握度</h2><p>根据最近练习结果</p></div></div><div class="card-body"><div class="knowledge-list"><div class="knowledge-item"><span class="label">一元一次方程</span><div class="progress-track"><div class="progress-fill" style="width:88%;background:#59a67c"></div></div><span class="value">88%</span></div><div class="knowledge-item"><span class="label">整式加减</span><div class="progress-track"><div class="progress-fill" style="width:82%;background:#59a67c"></div></div><span class="value">82%</span></div><div class="knowledge-item"><span class="label">绝对值方程</span><div class="progress-track"><div class="progress-fill" style="width:46%;background:#d77b28"></div></div><span class="value">46%</span></div><div class="knowledge-item"><span class="label">平行线与角</span><div class="progress-track"><div class="progress-fill" style="width:36%;background:#d77b28"></div></div><span class="value">36%</span></div></div></div></div></div>`; }
function taskDetail(){ return `<div class="page-head"><div><div class="eyebrow">任务详情</div><h1 class="page-title">${state.task.sourceFileName}</h1><p class="page-subtitle">李明 · 上传于 ${state.task.uploadedAt}</p></div><div class="head-actions"><button class="btn btn-secondary" data-action="more-actions">${icon('more')}更多操作</button></div></div><div class="card" style="margin-bottom:18px">${taskTimeline(state.task.status)}</div><div class="task-layout"><div class="card"><div class="card-head"><div><h2>任务概览</h2><p>识别结果和处理记录</p></div>${statusPill(state.task.status)}</div><div class="card-body"><div class="stats-grid" style="margin-bottom:0;grid-template-columns:repeat(3,1fr)"><div class="stat-card"><div class="stat-top"><span>识别题目</span></div><div class="stat-value">7</div><div class="stat-foot">已识别 7 道</div></div><div class="stat-card"><div class="stat-top"><span>错题</span></div><div class="stat-value">2</div><div class="stat-foot">1 道明确错误</div></div><div class="stat-card"><div class="stat-top"><span>待确认</span></div><div class="stat-value">2</div><div class="stat-foot">含 1 道冲突题</div></div></div></div></div><div class="card"><div class="card-head"><h2>下一步</h2></div><div class="card-body"><div class="detail-list"><div class="detail-item"><h3>家长确认</h3><p>确认明确错题，冲突题提交老师复核。</p><button class="btn btn-primary btn-sm mt-12" data-nav="confirm">去确认</button></div><div class="detail-item"><h3>辅助导出</h3><p>完成后可导出练习卷、教师答案或打印。</p><button class="btn btn-secondary btn-sm mt-12" data-action="export">打开导出选项</button></div></div></div></div></div>`; }
function studentView(){ switch(state.page){ case 'practiceDetail': return studentPractice(); case 'results': return studentResults(); case 'mistakes': return studentMistakes(); case 'progress': return progressView('student'); default:return studentToday(); } }
function studentToday(){ return `<div class="page-head"><div><div class="eyebrow">学生工作台 · ${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric'})}</div><h1 class="page-title">今天，完成一小步</h1><p class="page-subtitle">这里是只属于你的练习，不展示管理信息。</p></div></div><div class="stats-grid"><div class="stat-card"><div class="stat-top"><span>待完成练习</span><span class="stat-icon tint-orange">${icon('clock')}</span></div><div class="stat-value">1</div><div class="stat-foot">最晚 09-16 提交</div></div><div class="stat-card"><div class="stat-top"><span>本周完成</span><span class="stat-icon tint-green">${icon('check')}</span></div><div class="stat-value">4</div><div class="stat-foot">保持你的节奏</div></div><div class="stat-card"><div class="stat-top"><span>最近正确率</span><span class="stat-icon tint-blue">${icon('trend')}</span></div><div class="stat-value">83%</div><div class="stat-foot">比上周提高 9%</div></div><div class="stat-card"><div class="stat-top"><span>连续学习</span><span class="stat-icon tint-purple">${icon('book')}</span></div><div class="stat-value">6 天</div><div class="stat-foot">继续保持</div></div></div><div class="grid-2"><div class="card"><div class="card-head"><div><h2>待完成练习</h2><p>一次完成一题，专注解决问题</p></div><span class="pill pill-orange">今天</span></div><div class="card-body"><div class="list"><div class="list-row"><div class="row-thumb">${icon('book')}</div><div class="row-main"><strong>${state.practice.title}</strong><span>${state.practice.totalQuestions} 道题 · 约 20 分钟 · 截止 ${state.practice.dueAt}</span><div style="display:flex;gap:6px;margin-top:7px"><span class="pill pill-blue">绝对值方程</span><span class="pill pill-gray">标准</span></div></div><div class="row-right"><button class="btn btn-primary btn-sm" data-nav="practiceDetail">${icon('play')}开始练习</button></div></div></div></div></div><div class="card"><div class="card-head"><div><h2>已完成练习</h2><p>每一次提交都会留下进步</p></div></div><div class="card-body"><div class="empty-state"><div class="empty-icon">${icon('check')}</div><strong>本周已完成 4 份</strong><p>上一次练习正确率 83%，继续保持。</p><button class="btn btn-secondary btn-sm" data-nav="progress">查看学习进展</button></div></div></div></div>`; }
function studentPractice(){ const item=state.practice.items[state.currentQuestion]; const answer=state.draftAnswers[item.id]||''; const done=Object.keys(state.draftAnswers).length; return `<div class="page-head"><div><div class="eyebrow">在线练习 · ${state.practice.title}</div><h1 class="page-title">专注完成当前题</h1><p class="page-subtitle">答案会自动保存，提交后才会显示解析。</p></div><div class="head-actions"><span class="pill pill-blue">${done}/${state.practice.items.length} 已作答</span></div></div><div class="practice-layout"><div class="card number-nav"><h3>题目导航</h3><div class="number-grid">${state.practice.items.map((q,i)=>`<button class="number-btn ${i===state.currentQuestion?'current':''} ${state.draftAnswers[q.id]?'answered':''}" data-question-index="${i}">${i+1}</button>`).join('')}</div><div class="notice notice-info mt-18">${icon('lock')}<div>提交前不会显示正确答案。</div></div></div><div class="card practice-panel"><div class="practice-meta"><span>第 ${item.questionNo} 题 / ${state.practice.items.length}</span><span>${item.knowledgePoint}</span></div><div class="progress-track" style="margin-bottom:23px"><div class="progress-fill" style="width:${((state.currentQuestion+1)/state.practice.items.length)*100}%"></div></div><h2>${item.questionText}</h2>${item.questionType==='choice'?`<div class="choice-list">${item.options.map(opt=>`<label class="choice"><input type="radio" name="answer" value="${opt}" ${answer===opt?'checked':''}/><span>${opt}</span></label>`).join('')}</div>`:item.questionType==='blank'?`<div class="field"><label for="answer-input">填写答案</label><input id="answer-input" value="${answer}" placeholder="输入你的答案" /></div>`:`<div class="field"><label for="answer-input">写下你的解题过程</label><textarea id="answer-input" placeholder="可以先写思路，再写最终答案">${answer}</textarea><button class="btn btn-secondary btn-sm" data-action="upload-handwriting">${icon('image')}上传手写解题图片</button></div>`}<div class="practice-foot"><button class="btn btn-secondary btn-sm" data-action="prev" ${state.currentQuestion===0?'disabled':''}>上一题</button>${state.currentQuestion===state.practice.items.length-1?'<button class="btn btn-primary" data-action="submit-practice">提交练习</button>':'<button class="btn btn-primary" data-action="next">下一题 '+icon('arrow')+'</button>'}</div></div><aside class="card practice-side"><div class="card-head"><div><h2>完成进度</h2><p>慢一点也没关系</p></div></div><div class="card-body"><div class="progress-ring"><span>${Math.round((state.currentQuestion+1)/state.practice.items.length*100)}%</span></div><div class="side-stat"><strong>预计剩余 ${Math.max(3,(state.practice.items.length-state.currentQuestion-1)*4)} 分钟</strong>完成后会看到逐题解析</div><div class="notice notice-success mt-18">${icon('check')}<div><strong>自动保存已开启</strong>刚才的答案已保存到本地。</div></div></div></aside></div>`; }
function studentResults(){ if(!state.submission) return studentToday(); const results=state.submission.results; const correct=results.filter(r=>r.isCorrect).length; return `<div class="page-head"><div><div class="eyebrow">提交结果 · ${state.practice.title}</div><h1 class="page-title">这次练习完成了</h1><p class="page-subtitle">看看每一道题的结果和下一步建议。</p></div><div class="head-actions"><button class="btn btn-primary" data-action="again">再练一组 ${icon('arrow')}</button></div></div><div class="card result-hero"><div class="score"><div class="score-content"><strong>${Math.round(correct/results.length*100)}</strong><span>本次得分</span></div></div><div><h2 class="result-title">完成得很好，继续保持专注</h2><p>你答对了 ${correct} 道，错题会在解析里标出关键步骤。</p><div class="result-cards"><div class="result-mini"><span>正确题数</span><strong>${correct}</strong></div><div class="result-mini"><span>需要再看</span><strong>${results.length-correct}</strong></div><div class="result-mini"><span>用时</span><strong>16 分钟</strong></div></div></div></div><div class="card section-gap"><div class="card-head"><div><h2>逐题结果与解析</h2><p>提交后开放答案、分步解析和易错提醒</p></div></div><div class="card-body">${results.map((r,i)=>`<article class="question-card"><div class="question-head"><span class="question-no">第 ${i+1} 题</span><span class="pill ${r.isCorrect?'pill-green':'pill-red'}">${r.isCorrect?'回答正确':'再看一遍'}</span></div><p class="question-text">${state.practice.items[i].questionText}</p><div class="answer-box"><div><label>你的答案</label><span>${r.studentAnswer || '未作答'}</span></div><div><label>正确答案</label><span>${r.correctAnswer}</span></div></div><div class="notice ${r.isCorrect?'notice-success':'notice-info'}">${icon(r.isCorrect?'check':'help')}<div><strong>${r.isCorrect?'做对了，继续保持。':'关键步骤'}</strong>${r.explanation}</div></div><div style="margin-top:9px"><span class="pill pill-blue">${state.practice.items[i].knowledgePoint}</span></div></article>`).join('')}</div></div>`; }
function studentMistakes(){ const qs=state.task.questions.filter(q=>q.teacherMarkingResult==='incorrect'); return `<div class="page-head"><div><div class="eyebrow">我的错题</div><h1 class="page-title">把不会的题，变成会做的题</h1><p class="page-subtitle">只展示已经确认的错题和练习建议。</p></div></div><div class="card"><div class="card-head"><div><h2>待强化错题</h2><p>${qs.length} 道题 · 按最近出现排序</p></div></div><div class="card-body">${qs.map(q=>`<article class="question-card"><div class="question-head"><span class="question-no">第 ${q.questionNo} 题 · ${q.knowledgePoint}</span><span class="pill pill-orange">待强化</span></div><p class="question-text">${q.questionText}</p><div class="answer-box"><div><label>我的作答</label><span>${q.studentWork}</span></div><div><label>易错类型</label><span>${q.errorType}</span></div></div><button class="btn btn-primary btn-sm" data-nav="practiceDetail">开始同类练习</button></article>`).join('')}</div></div>`; }
function teacherView(){ switch(state.page){ case 'review': return teacherReview(); case 'diagnosis': return teacherDiagnosis(); case 'assign': return teacherAssign(); case 'students': return teacherStudents(); case 'taskDetail': return taskDetail(); default:return teacherReview(); } }
function teacherReview(){ return `<div class="page-head"><div><div class="eyebrow">老师工作台 · 需要你的判断</div><h1 class="page-title">待复核</h1><p class="page-subtitle">优先处理批改冲突、低置信度和题目条件不足的任务。</p></div><div class="head-actions"><button class="btn btn-secondary" data-action="refresh">${icon('clock')}刷新列表</button></div></div><div class="stats-grid"><div class="stat-card"><div class="stat-top"><span>待复核题目</span><span class="stat-icon tint-orange">${icon('alert')}</span></div><div class="stat-value">8</div><div class="stat-foot">较昨日减少 3 道</div></div><div class="stat-card"><div class="stat-top"><span>批改冲突</span><span class="stat-icon tint-red">${icon('help')}</span></div><div class="stat-value">3</div><div class="stat-foot">需要人工判断</div></div><div class="stat-card"><div class="stat-top"><span>低置信度</span><span class="stat-icon tint-purple">${icon('image')}</span></div><div class="stat-value">4</div><div class="stat-foot">识别结果需确认</div></div><div class="stat-card"><div class="stat-top"><span>今日已完成</span><span class="stat-icon tint-green">${icon('check')}</span></div><div class="stat-value">12</div><div class="stat-foot">处理效率良好</div></div></div><div class="card"><div class="filter-bar"><select><option>全部班级</option><option>初一（3）班</option></select><select><option>全部学生</option><option>李明</option></select><select><option>全部知识点</option><option>平行线与角</option><option>绝对值方程</option></select><select><option>全部冲突类型</option><option>批改冲突</option><option>条件不足</option></select><button class="btn btn-secondary btn-sm" data-action="apply-filter">${icon('filter')}筛选</button></div><div class="table-wrap"><table><thead><tr><th>优先级</th><th>学生 / 班级</th><th>题目</th><th>问题类型</th><th>识别置信度</th><th>提交时间</th><th></th></tr></thead><tbody><tr><td><span class="pill pill-red">高</span></td><td><strong>李明</strong><br><span class="muted">初一（3）班</span></td><td>第 7 题 · 平行线与角</td><td><span class="pill pill-orange">教师批改冲突</span></td><td>低</td><td>今天 09:12</td><td><button class="btn btn-primary btn-sm" data-action="review-question">开始复核</button></td></tr><tr><td><span class="pill pill-orange">中</span></td><td><strong>陈思远</strong><br><span class="muted">初一（3）班</span></td><td>第 4 题 · 一元一次方程</td><td><span class="pill pill-purple">低置信度</span></td><td>中</td><td>今天 08:46</td><td><button class="btn btn-secondary btn-sm" data-action="review-question">开始复核</button></td></tr><tr><td><span class="pill pill-orange">中</span></td><td><strong>周可欣</strong><br><span class="muted">初一（2）班</span></td><td>第 9 题 · 统计图</td><td><span class="pill pill-gray">条件不足</span></td><td>低</td><td>昨天 17:30</td><td><button class="btn btn-secondary btn-sm" data-action="review-question">开始复核</button></td></tr></tbody></table></div></div>`; }
function teacherDiagnosis(){ return `<div class="page-head"><div><div class="eyebrow">老师工作台 · 初一（3）班</div><h1 class="page-title">班级诊断</h1><p class="page-subtitle">从班级共性问题出发，决定下一次练习布置。</p></div><div class="head-actions"><select class="field select" style="height:42px;padding:0 12px;border:1px solid #d8e0eb;border-radius:9px"><option>近 30 天</option><option>近 7 天</option></select><button class="btn btn-secondary" data-action="export">${icon('download')}导出诊断</button></div></div><div class="stats-grid"><div class="stat-card"><div class="stat-top"><span>班级错题总数</span><span class="stat-icon tint-orange">${icon('alert')}</span></div><div class="stat-value">126</div><div class="stat-foot">近 30 天</div></div><div class="stat-card"><div class="stat-top"><span>覆盖学生</span><span class="stat-icon tint-blue">${icon('users')}</span></div><div class="stat-value">42</div><div class="stat-foot">班级共 45 人</div></div><div class="stat-card"><div class="stat-top"><span>练习完成率</span><span class="stat-icon tint-green">${icon('check')}</span></div><div class="stat-value">86%</div><div class="stat-foot">较上周期 +8%</div></div><div class="stat-card"><div class="stat-top"><span>待复核</span><span class="stat-icon tint-purple">${icon('clock')}</span></div><div class="stat-value">8</div><div class="stat-foot">建议今日处理</div></div></div><div class="grid-2"><div class="card"><div class="card-head"><div><h2>高频知识点排行</h2><p>点击条目查看对应题目</p></div></div><div class="card-body"><div class="chart-bars"><button class="bar-row" data-action="drilldown"><span>绝对值方程</span><span class="bar-bg"><span class="bar-fill" style="width:88%"></span></span><strong>36</strong></button><button class="bar-row" data-action="drilldown"><span>平行线与角</span><span class="bar-bg"><span class="bar-fill" style="width:67%;background:#d77b28"></span></span><strong>27</strong></button><button class="bar-row" data-action="drilldown"><span>整式加减</span><span class="bar-bg"><span class="bar-fill" style="width:51%;background:#6f8fc3"></span></span><strong>19</strong></button><button class="bar-row" data-action="drilldown"><span>统计图表</span><span class="bar-bg"><span class="bar-fill" style="width:38%;background:#72b78d"></span></span><strong>15</strong></button><button class="bar-row" data-action="drilldown"><span>百分数应用</span><span class="bar-bg"><span class="bar-fill" style="width:28%;background:#a9b5c6"></span></span><strong>11</strong></button></div></div></div><div class="card"><div class="card-head"><div><h2>错误类型分布</h2><p>共 126 道错题</p></div></div><div class="card-body"><div class="donut-wrap"><div class="donut"></div><div class="legend"><span><i style="background:#2c67c7"></i>概念混淆 · 46%</span><span><i style="background:#f0a449"></i>计算错误 · 26%</span><span><i style="background:#72b78d"></i>漏解漏答 · 18%</span><span><i style="background:#b4bfd0"></i>条件不足 · 10%</span></div></div></div></div></div><div class="card section-gap"><div class="card-head"><div><h2>学生知识点矩阵</h2><p>色块越深代表近期错题越集中，点击姓名查看个人错题</p></div><span class="pill pill-gray">45 人</span></div><div class="card-body"><div class="heat-table"><table><thead><tr><th>学生</th><th>绝对值方程</th><th>平行线与角</th><th>整式加减</th><th>统计图表</th><th>练习完成率</th></tr></thead><tbody><tr><td><button class="btn btn-ghost btn-sm" data-action="student-drill">李明</button></td><td><span class="heat heat-high">高</span></td><td><span class="heat heat-mid">中</span></td><td><span class="heat heat-low">低</span></td><td><span class="heat heat-low">低</span></td><td>83%</td></tr><tr><td><button class="btn btn-ghost btn-sm" data-action="student-drill">陈思远</button></td><td><span class="heat heat-mid">中</span></td><td><span class="heat heat-high">高</span></td><td><span class="heat heat-mid">中</span></td><td><span class="heat heat-low">低</span></td><td>76%</td></tr><tr><td><button class="btn btn-ghost btn-sm" data-action="student-drill">周可欣</button></td><td><span class="heat heat-low">低</span></td><td><span class="heat heat-mid">中</span></td><td><span class="heat heat-high">高</span></td><td><span class="heat heat-mid">中</span></td><td>91%</td></tr></tbody></table></div></div></div>`; }
function teacherAssign(){ return `<div class="page-head"><div><div class="eyebrow">老师工作台 · 发布任务</div><h1 class="page-title">练习布置</h1><p class="page-subtitle">按班级和知识点布置一份清晰、可完成的练习。</p></div><div class="head-actions"><button class="btn btn-primary" data-action="publish">${icon('send')}发布练习</button></div></div><div class="grid-2"><div class="card"><div class="card-head"><div><h2>练习设置</h2><p>发布前可预览题目范围</p></div></div><div class="card-body"><div class="field"><label for="class-select">布置给</label><select id="class-select"><option>初一（3）班 · 45 人</option><option>指定学生：李明</option></select></div><div class="field"><label>知识点</label><div style="display:flex;gap:7px;flex-wrap:wrap"><span class="pill pill-blue">绝对值方程 ×</span><span class="pill pill-blue">一元一次方程 ×</span><button class="btn btn-secondary btn-sm" data-action="choose-knowledge">添加知识点</button></div></div><div class="field-row"><div class="field"><label for="count">题量</label><select id="count"><option>6 道</option><option>10 道</option><option>15 道</option></select></div><div class="field"><label for="assign-diff">难度</label><select id="assign-diff"><option>基础</option><option selected>标准</option><option>提高</option></select></div></div><div class="field"><label for="due-date">截止时间</label><input id="due-date" type="date" value="2026-09-16" /></div><div class="field"><label class="check-row"><input type="checkbox" checked /> 混入本班高频错题</label></div></div></div><div class="card"><div class="card-head"><div><h2>发布前预览</h2><p>学生端只会看到题目与截止时间</p></div><span class="pill pill-green">已生成 6 题</span></div><div class="card-body"><div class="detail-list"><div class="detail-item"><h3>绝对值方程 · 4 题</h3><p>包含绝对值定义、分类讨论和含绝对值方程。</p></div><div class="detail-item"><h3>一元一次方程 · 2 题</h3><p>包含移项、合并同类项和检验答案。</p></div><div class="notice notice-info">${icon('clock')}<div><strong>预计完成时间：20 分钟</strong>发布后学生会收到待完成提醒。</div></div></div></div></div></div>`; }
function teacherStudents(){ return `<div class="page-head"><div><div class="eyebrow">老师工作台 · 初一（3）班</div><h1 class="page-title">学生管理</h1><p class="page-subtitle">查看个人练习进度和知识点分布。</p></div><div class="head-actions"><button class="btn btn-secondary" data-action="export">${icon('download')}导出名单</button></div></div><div class="card"><div class="filter-bar"><div style="position:relative;flex:1;min-width:180px"><span style="position:absolute;left:10px;top:10px;color:#8693a6">${icon('search')}</span><input style="width:100%;padding-left:34px" placeholder="搜索学生姓名" /></div><select><option>全部状态</option><option>需要关注</option><option>进步明显</option></select></div><div class="table-wrap"><table><thead><tr><th>学生</th><th>近 7 天练习</th><th>正确率</th><th>薄弱知识点</th><th>最近活动</th><th></th></tr></thead><tbody><tr><td><strong>李明</strong></td><td>4 份</td><td><span class="pill pill-green">83%</span></td><td>绝对值方程</td><td>今天 10:24</td><td><button class="btn btn-secondary btn-sm" data-action="student-detail">查看</button></td></tr><tr><td><strong>陈思远</strong></td><td>3 份</td><td><span class="pill pill-orange">76%</span></td><td>平行线与角</td><td>今天 09:50</td><td><button class="btn btn-secondary btn-sm" data-action="student-detail">查看</button></td></tr><tr><td><strong>周可欣</strong></td><td>5 份</td><td><span class="pill pill-green">91%</span></td><td>整式加减</td><td>昨天 18:12</td><td><button class="btn btn-secondary btn-sm" data-action="student-detail">查看</button></td></tr></tbody></table></div></div>`; }
function bindEvents(){ document.querySelectorAll('[data-nav]').forEach(el=>el.addEventListener('click',()=>{ const target=el.dataset.nav; if(target==='upload'&&!permissions[state.role].uploadWorksheet) return showToast('当前角色没有上传作业权限','warn'); if(target==='confirm'&&!permissions[state.role].confirmRecognition) return showToast('当前角色没有确认识别结果权限','warn'); if(target==='practice'&&!permissions[state.role].createPractice) return showToast('当前角色没有生成练习权限','warn'); state.page=target; saveState(); render(); }));
  const role=document.querySelector('#role-switch'); if(role) role.addEventListener('change',e=>{ state.role=e.target.value; state.page=roleMeta[state.role].nav[0][0]; state.submitted=false; saveState(); render(); showToast(`已切换为${roleMeta[state.role].role}视角`,'success'); });
  document.querySelectorAll('[data-question-check]').forEach(el=>el.addEventListener('change',e=>{ const id=e.target.dataset.questionCheck; state.selectedQuestions=e.target.checked?[...new Set([...state.selectedQuestions,id])]:state.selectedQuestions.filter(x=>x!==id); saveState(); render(); }));
  document.querySelectorAll('[data-question-index]').forEach(el=>el.addEventListener('click',()=>{ state.currentQuestion=Number(el.dataset.questionIndex); saveState(); render(); }));
  const input=document.querySelector('#answer-input'); if(input) input.addEventListener('input',e=>{ state.draftAnswers[state.practice.items[state.currentQuestion].id]=e.target.value; saveState(); });
  document.querySelectorAll('input[name="answer"]').forEach(el=>el.addEventListener('change',e=>{ state.draftAnswers[state.practice.items[state.currentQuestion].id]=e.target.value; saveState(); render(); }));
  document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>handleAction(el.dataset.action,el.dataset.id)));
  document.querySelectorAll('[data-action="timeline"]').forEach(el=>el.addEventListener('keydown',e=>{ if(e.key==='Enter'||e.key===' ') handleAction('timeline',el.dataset.status); }));
}
function handleAction(action,id){ if(action==='choose-file'){ document.querySelector('#file-input')?.click(); return; } if(action==='notifications'){ return showToast('暂无新的通知'); } if(action==='help'){ return showToast('遇到识别冲突时，提交老师复核即可。'); } if(action==='resync'){ state.task.saveStatus='success'; state.task.saveErrorMessage=''; saveState(); render(); return showToast('已重新同步到历史记录','success'); } if(action==='confirm-question'){ const q=state.task.questions.find(x=>x.id===id); if(q){q.reviewStatus='parent_confirmed'; state.selectedQuestions=[...new Set([...state.selectedQuestions,id])]; saveState(); render(); showToast(`第 ${q.questionNo} 题已确认`,'success'); } return; } if(action==='send-review'){ const q=state.task.questions.find(x=>x.id===id); if(q){q.reviewStatus='pending'; state.task.status='needs_teacher_review'; saveState(); render(); showToast('已提交老师复核','success'); } return; } if(action==='not-mistake'){ state.task.questions=state.task.questions.filter(q=>q.id!==id); state.selectedQuestions=state.selectedQuestions.filter(x=>x!==id); saveState(); render(); return showToast('已标记为不是错题'); } if(action==='edit-question'){ return showModal('修改识别内容',`<div class="field"><label>题目内容</label><textarea id="edit-text">${state.task.questions.find(q=>q.id===id)?.questionText||''}</textarea></div><div class="field"><label>学生作答</label><input id="edit-answer" value="${state.task.questions.find(q=>q.id===id)?.studentWork||''}" /></div>`,()=>{ const q=state.task.questions.find(x=>x.id===id); if(q){q.questionText=document.querySelector('#edit-text').value;q.studentWork=document.querySelector('#edit-answer').value;q.recognitionConfidence='high'; saveState(); render(); showToast('识别内容已更新','success'); }}); } if(action==='generate'){ if(!state.selectedQuestions.some(id=>state.task.questions.find(q=>q.id===id)?.conflictStatus!=='teacher_marking_conflict')) return showToast('请至少选择一道可用于练习的错题','warn'); state.task.status='generating'; saveState(); render(); setTimeout(()=>{state.task.status='ready_for_practice';state.practice.status='assigned';saveState();render();showToast('练习已生成，可在学生端开始作答','success');},900); return; } if(action==='prev'){state.currentQuestion=Math.max(0,state.currentQuestion-1);saveState();render();return;} if(action==='next'){state.currentQuestion=Math.min(state.practice.items.length-1,state.currentQuestion+1);saveState();render();return;} if(action==='submit-practice'){ const unanswered=state.practice.items.filter(q=>!state.draftAnswers[q.id]); if(unanswered.length) return showModal('还有题目没有作答',`<div class="notice notice-warn">${icon('alert')}<div><strong>还有 ${unanswered.length} 道题未作答</strong>你可以返回补充，也可以直接提交。</div></div>`,()=>submitPractice()); return submitPractice(); } if(action==='upload-handwriting') return showToast('演示版本已记录图片入口，实际上传将在此处接入'); if(action==='again'){state.page='practiceDetail';state.currentQuestion=0;state.draftAnswers={};state.submission=null;saveState();render();return;} if(action==='review-question'){state.page='taskDetail';state.role='teacher';saveState();render();return showToast('已打开复核详情');} if(action==='publish'){return showModal('确认发布练习',`<div class="notice notice-info">${icon('send')}<div><strong>将发布给初一（3）班 45 人</strong>共 6 道题，截止时间 2026-09-16。</div></div>`,()=>{showToast('练习已发布给全班学生','success');});} if(action==='refresh'||action==='apply-filter') return showToast('列表已更新','success'); if(action==='drilldown'||action==='student-drill') return showToast('已筛选到对应题目列表'); if(action==='student-detail') return showToast('已打开李明的个人进展'); if(action==='choose-knowledge') return showToast('知识点选择器已打开（演示）'); if(action==='export'||action==='more-actions') return showModal('更多操作',`<div class="detail-list"><button class="btn btn-secondary" data-action="download-real">${icon('download')}导出学生练习卷</button><button class="btn btn-secondary" data-action="download-real">${icon('download')}导出教师答案与解析</button><button class="btn btn-secondary" data-action="download-real">${icon('download')}打印练习</button><button class="btn btn-secondary" data-action="download-real">${icon('send')}复制分享链接</button></div>`); if(action==='download-real') return showToast('导出任务已创建，完成后会在通知中心提示','success'); if(action==='timeline') return showToast(`状态节点：${statusLabel(id)}`); }
function submitPractice(){ const results=state.practice.items.map(item=>({practiceItemId:item.id,studentAnswer:state.draftAnswers[item.id]||'',correctAnswer:item.correctAnswer,isCorrect:(state.draftAnswers[item.id]||'').trim()===item.correctAnswer,explanation:item.explanation})); state.submission={id:'sub-'+Date.now(),practiceSetId:state.practice.id,studentId:'stu-001',answers:state.draftAnswers,submittedAt:new Date().toISOString(),score:Math.round(results.filter(r=>r.isCorrect).length/results.length*100),results}; state.practice.status='completed'; state.task.status='completed'; state.page='results'; saveState(); render(); showToast('已提交，解析已开放','success'); }
function showModal(title,body,onConfirm){ const wrap=document.createElement('div'); wrap.className='modal-backdrop'; wrap.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${title}</h2><button class="close-btn" data-close>${icon('close')}</button></div><div class="modal-body">${body}</div>${onConfirm?'<div class="modal-foot"><button class="btn btn-secondary" data-close>取消</button><button class="btn btn-primary" data-confirm>确认</button></div>':''}</div>`; document.body.appendChild(wrap); wrap.querySelectorAll('[data-close]').forEach(el=>el.addEventListener('click',()=>wrap.remove())); if(onConfirm) wrap.querySelector('[data-confirm]').addEventListener('click',()=>{onConfirm();wrap.remove();}); }
function teacherReviewDetail(){ const q=state.task.questions.find(item=>item.conflictStatus==='teacher_marking_conflict') || state.task.questions[0]; return `<div class="page-head"><div><div class="eyebrow">老师工作台 · 复核详情</div><h1 class="page-title">复核第 ${q.questionNo} 题</h1><p class="page-subtitle">${state.task.sourceFileName} · 李明 · 初一（3）班</p></div><div class="head-actions"><button class="btn btn-secondary" data-nav="review">返回待复核</button></div></div><div class="notice notice-warn" style="margin-bottom:18px">${icon('alert')}<div><strong>教师批改与数学复核结果不一致</strong>请根据原始图片和题目条件做最终判断，保存后才会更新练习范围。</div></div><div class="card" style="margin-bottom:18px">${taskTimeline('needs_teacher_review')}</div><div class="split" style="grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr)"><div class="card"><div class="card-head"><div><h2>原始作业图片</h2><p>可放大、旋转查看</p></div></div><div class="card-body"><div class="task-image"><div class="worksheet-lines"></div><div class="image-tools"><button class="image-tool" data-action="zoom" aria-label="放大">${icon('expand')}</button><button class="image-tool" data-action="rotate" aria-label="旋转">${icon('rotate')}</button></div></div></div></div><div class="card"><div class="card-head"><div><h2>数学复核</h2><p>展示结构化结果，不展示模型推理过程</p></div><span class="pill pill-orange">待处理</span></div><div class="card-body"><div class="question-card" style="margin:0 0 14px"><div class="question-head"><span class="question-no">第 ${q.questionNo} 题 · ${q.knowledgePoint}</span><span class="pill pill-red">低置信度</span></div><p class="question-text">${q.questionText}</p><div class="answer-box"><div><label>学生作答</label><span>${q.studentWork}</span></div><div><label>教师原始批改</label><span>错误 · ${q.teacherWrittenAnswer}</span></div><div><label>AI 数学复核</label><span>条件不足，无法判断唯一答案</span></div><div><label>识别正确答案</label><span>${q.verifiedCorrectAnswer}</span></div></div><div class="field"><label for="review-knowledge">知识点</label><select id="review-knowledge"><option selected>${q.knowledgePoint}</option><option>三角形内角和</option><option>平行线与角</option></select></div><div class="field"><label for="review-answer">最终正确答案</label><input id="review-answer" value="${q.verifiedCorrectAnswer}" /></div><div class="field"><label for="review-note">复核备注</label><textarea id="review-note">${q.knowledgeExplanation || ''}</textarea></div></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-primary" data-action="teacher-confirm" data-id="${q.id}">${icon('check')}确认 AI 判断</button><button class="btn btn-secondary" data-action="teacher-correct" data-id="${q.id}">${icon('edit')}修改并保存</button><button class="btn btn-danger" data-action="teacher-reject" data-id="${q.id}">驳回重新识别</button></div></div></div></div>`; }
const baseBindEvents = bindEvents;
bindEvents = function(){ baseBindEvents(); const fileInput=document.querySelector('#file-input'); if(fileInput) fileInput.addEventListener('change',e=>{ const file=e.target.files?.[0]; if(!file) return; if(file.size>10*1024*1024) return showToast('图片超过 10MB，请选择更小的文件','warn'); state.task.sourceFileName=file.name; state.task.status='recognizing'; saveState(); render(); showToast('图片已上传，AI 正在识别…'); setTimeout(()=>{ state.task.status='needs_confirmation'; saveState(); render(); showToast('识别完成，请确认结果','success'); },1200); }); };
const baseTaskDetail = taskDetail;
taskDetail = function(){ if(state.role==='teacher') return teacherReviewDetail(); return baseTaskDetail(); };
const baseHandleAction = handleAction;
handleAction = function(action,id){ if((action==='teacher-confirm'||action==='teacher-correct') && state.role==='teacher'){ const q=state.task.questions.find(x=>x.id===id); if(q){ q.reviewStatus='teacher_confirmed'; q.conflictStatus='none'; q.aiMathVerdict='incorrect'; q.verifiedCorrectAnswer=document.querySelector('#review-answer')?.value || q.verifiedCorrectAnswer; q.knowledgePoint=document.querySelector('#review-knowledge')?.value || q.knowledgePoint; state.task.status='confirmed'; saveState(); render(); showToast('复核结果已保存，题目已从冲突列表移除','success'); } return; } if(action==='teacher-reject' && state.role==='teacher'){ const q=state.task.questions.find(x=>x.id===id); if(q){ q.reviewStatus='pending'; state.task.status='recognizing'; saveState(); render(); showToast('已驳回，任务进入重新识别','success'); } return; } return baseHandleAction(action,id); };
const reviewAction = handleAction;
handleAction = function(action,id){ if(state.role==='teacher' && (action==='teacher-confirm'||action==='teacher-correct'||action==='teacher-reject')){ reviewAction(action,id); state.page='review'; saveState(); render(); return; } return reviewAction(action,id); };
const originalRender=render; render=()=>{ originalRender(); };
render();
